  function unitPicker(){return `<div class="ac-unit-picker" role="group" aria-label="${esc(t('Choose a chapter'))}">${units.map((u,i)=>`<button type="button" data-ac="unit" data-value="${u.id}" aria-pressed="${unitId===u.id}" class="${unitId===u.id?'is-active':''}"><span>0${i+1}</span><span>${u.title}<small>${t('{done} / {total} missions',{done:u.lessons.filter(id=>state.completed[id]).length,total:u.lessons.length})}</small></span>${u.lessons.every(id=>state.completed[id])?'<b aria-label="Completed">✓</b>':''}</button>`).join('')}</div>`;}
